import { registerModule } from '../../core/lifecycle';
import { watchElement } from '../../core/observer';
import { schedule } from '../../core/scheduler';

const HERO_ID = 'ptv-home-hero';

let hero;
let stopWatching;

function getHomePage() {
    return document.querySelector('.homePage');
}

function getCards(root = document) {
    return Array.from(
        root.querySelectorAll(
            '.card:not(.hide), .virtualScrollItem .card'
        )
    );
}

function getCardImage(card) {
    if (!card) return '';

    const img =
        card.querySelector('img[data-src]')
        || card.querySelector('img[src]')
        || card.querySelector('img');

    if (img) {
        return (
            img.currentSrc
            || img.src
            || img.dataset.src
            || ''
        );
    }

    const bg =
        card.querySelector('.cardImageContainer')
        || card.querySelector('.cardImage')
        || card.querySelector('.cardPadder');

    if (!bg) return '';

    const style = getComputedStyle(bg).backgroundImage;

    if (!style || style === 'none') {
        return '';
    }

    const match = /url\((["']?)(.*?)\1\)/.exec(style);

    return match?.[2] || '';
}

function getCardTitle(card) {
    return (
        card.querySelector('.cardText')?.textContent?.trim()
        || card.querySelector('.cardScalableText')?.textContent?.trim()
        || card.getAttribute('title')
        || card.getAttribute('aria-label')
        || ''
    );
}

function getFeaturedCard(cards) {
    return cards.find((card) => {
        const image = getCardImage(card);
        const title = getCardTitle(card);

        return (
            image
            && title
            && !image.includes('/icons/')
            && !image.includes('data:image')
        );
    });
}

function createHero() {
    if (hero) return hero;

    hero = document.createElement('section');
    hero.id = HERO_ID;
    hero.className = 'ptv-home-hero ptv-loading';
    hero.style.display = 'none';

    hero.innerHTML = `
        <div class="ptv-hero-backdrop"></div>

        <div class="ptv-hero-overlay"></div>

        <div class="ptv-hero-content">
            <div class="ptv-hero-kicker">Featured</div>
            <h1 class="ptv-hero-title"></h1>

            <div class="ptv-hero-buttons">
                <button class="ptv-hero-button ptv-hero-play">
                    Play
                </button>

                <button class="ptv-hero-button ptv-hero-info">
                    More Info
                </button>
            </div>
        </div>
    `;

    return hero;
}

function updateHero() {
    const home = getHomePage();

    if (!home) return;

    const heroEl = createHero();

    if (!heroEl.parentNode) {
        home.prepend(heroEl);
    }

    const cards = getCards(home);

    if (!cards.length) return;

    const featured = getFeaturedCard(cards);

    if (!featured) return;

    const image = getCardImage(featured);
    const title = getCardTitle(featured);

    if (!image || !title) return;

    if (heroEl.dataset.image === image) {
        return;
    }

    heroEl.dataset.image = image;

    heroEl
        .querySelector('.ptv-hero-backdrop')
        .style.backgroundImage = `url("${image}")`;

    heroEl
        .querySelector('.ptv-hero-title')
        .textContent = title;

    heroEl.classList.remove('ptv-loading');


}

function init() {
    schedule('ptv-home-hero-init', () => {
        updateHero();

        stopWatching = watchElement(
            '.homePage .sections',
            () => {
                schedule('ptv-home-hero-update', setTimeout(updateHero, 250));
            }
        );
    });
}

function destroy() {
    stopWatching?.();
    stopWatching = null;
}

registerModule({
    name: 'home-hero',
    routes: ['home'],
    init,
    destroy,
    refresh: updateHero
});
